import numpy as np, warnings
from hera.analysis import open_run, resolve_channels, sdh_onset, sdh_fft, SdhOnsetError
from scipy.signal import find_peaks
r = open_run("data/6"); ch = {cc.cid: cc for cc in resolve_channels(r.metadata)}
B = r.col("magnet_field"); R = (r.col("sr1_X")/ch["sr1"].gain)/(r.col("sr0_X")/ch["sr0"].gain)
for blo in (0.9, 1.0, 1.2):
    print(f"--- sdh_onset run 6, b_lo={blo}")
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        try:
            on = sdh_onset(R, B, b_lo=blo, r_full_scale=5000); print(on.summary())
        except SdhOnsetError as e: print("ERR", e)
        for ww in w: print("  warn:", str(ww.message)[:200])
for lo, hi in ((1.0,10),(1.2,10),(1.2,5),(1.2,3),(3,10),(5,10),(1.5,10)):
    f, sp = sdh_fft(R[:, None], B, b_range=(lo, hi), bg_degree=5, log=False, nfft=4096)
    s = sp[0]/sp[0].max(); pk, _ = find_peaks(s, prominence=0.04); pk = sorted(pk, key=lambda p: -s[p])[:7]
    print(f"FFT [{lo},{hi}] dF={1/(1/lo-1/hi):.2f} T: " + ", ".join(f"{f[p]:.1f}T({s[p]:.2f})" for p in sorted(pk)))
# raw envelope: oscillation swing per 0.25 T bin, 1..3 T
m = (B>=0.9)&(B<=3.0); cf = np.polyfit(B[m], R[m], 5); dR = R[m]-np.polyval(cf, B[m]); Bm = B[m]
for lo in np.arange(0.9, 3.0, 0.25):
    k = (Bm>=lo)&(Bm<lo+0.25); print(f"  B {lo:.2f}-{lo+0.25:.2f}: dR pk-pk {np.ptp(dR[k]):.1f} Ohm, R {R[m][k].min():.1f}..{R[m][k].max():.1f}")
EOF

